selector_to_html = {"a[href=\"#step-2-get-the-scripts\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Step 2 Get the scripts<a class=\"headerlink\" href=\"#step-2-get-the-scripts\" title=\"Link to this heading\">#</a></h2><p>The dedicated work directory separates the compiler, Python environment, and caches from other installations. Keep the full script directory; <code class=\"docutils literal notranslate\"><span class=\"pre\">run.sh</span></code> depends on its companion files.</p>", "a[href=\"#enable-flagtree-cpu-on-arm64\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Enable FlagTree CPU on Arm64<a class=\"headerlink\" href=\"#enable-flagtree-cpu-on-arm64\" title=\"Link to this heading\">#</a></h1><p><a class=\"reference external\" href=\"https://github.com/flagos-ai/flagtree-cpu/tree/triton_v3.7.x\">FlagTree CPU</a> provides a CPU backend for Triton, allowing kernels written with Triton\u2019s Python API to compile and run on CPUs. Its compiler lowers Triton kernels through MLIR/LLVM into native CPU code, while its runtime handles CPU target selection, kernel launches, and compilation caching. This guide covers the Triton 3.7.2 implementation on Linux Arm64 and validates it with a vector-add kernel and FlagGems W4A8 operator tests.</p><p>Build and validate the Triton 3.7.2 CPU backend using the scripts in <a class=\"reference external\" href=\"https://github.com/flagos-ai/community/tree/main/fep/sig-edge/scripts/flagtree-cpu37\">flagos-ai/community</a>. Follow these steps in the same shell.</p>", "a[href=\"#step-4-validate-cpu-execution\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Step 4 Validate CPU execution<a class=\"headerlink\" href=\"#step-4-validate-cpu-execution\" title=\"Link to this heading\">#</a></h2><p>Tests check source/toolchain revisions and the CPU target, execute a real vector-add kernel with fresh and reused caches, and compare FlagGems W4A8 results against PyTorch. Acceptance requires <strong>7 passed, 0 skipped</strong>. Logs and test reports are saved under <code class=\"docutils literal notranslate\"><span class=\"pre\">$WORK_DIR/logs/</span></code>.</p>", "a[href=\"#step-5-enable-the-backend-for-your-application\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Step 5 Enable the backend for your application<a class=\"headerlink\" href=\"#step-5-enable-the-backend-for-your-application\" title=\"Link to this heading\">#</a></h2><p>Replace <code class=\"docutils literal notranslate\"><span class=\"pre\">your_program.py</span></code> with your application. <code class=\"docutils literal notranslate\"><span class=\"pre\">TRITON_CPU_BACKEND=1</span></code> selects CPU execution; <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGGEMS_VENDOR=arm</span></code> selects the FlagGems Arm implementation. A persistent cache lets compatible kernel specializations reuse compiled code. These variables must be exported in your application shell because the setup/test scripts run in separate Bash processes.</p><p>Passing these checks validates the compiler and tested operators; model integration and model cold-start performance require separate validation.</p>", "a[href=\"#step-3-build-and-install\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Step 3 Build and install<a class=\"headerlink\" href=\"#step-3-build-and-install\" title=\"Link to this heading\">#</a></h2><p>Setup installs system dependencies, creates a Python 3.11 environment, fetches pinned FlagTree CPU and FlagGems revisions, initializes submodules, and builds Triton 3.7.2. Pinned LLVM and SLEEF versions make the build reproducible. The installed package imports as <code class=\"docutils literal notranslate\"><span class=\"pre\">triton</span></code>.</p>", "a[href=\"#step-1-prepare-the-host\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Step 1 Prepare the host<a class=\"headerlink\" href=\"#step-1-prepare-the-host\" title=\"Link to this heading\">#</a></h2><p>Use <strong>Debian 13 on Linux Arm64 (<code class=\"docutils literal notranslate\"><span class=\"pre\">aarch64</span></code>)</strong>, with Git installed, sudo access (or root), and at least <strong>25 GiB free disk space</strong>. Ensure the host can reach the source repositories and dependency download services.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
